<template>
<section><div class="page-head"><div><span class="eyebrow">Preferences</span><h1 class="page-title">Settings</h1><p class="muted">Personalize your LogoRemakeFour Media Center.</p></div></div><div class="card"><div class="settings-line"><div><strong>Appearance</strong><div class="muted">Dark theme</div></div><span class="callout">Enabled</span></div><div class="settings-line"><div><strong>Volume</strong><div class="muted">Adjust the player volume</div></div><input type="range" min="0" max="100" v-model="state.volume" aria-label="Volume"></div><div class="settings-line"><div><strong>Media folders</strong><div class="muted">Pick up to five folders in this session</div></div><button class="button-secondary" @click="$emit('action',{action:'folder-select'})">Add Folder</button></div><div class="settings-line"><div><strong>Installed add-ons</strong><div class="muted">{{state.installed.length}} add-ons installed</div></div><button class="button-secondary" @click="$emit('navigate','addons')">Manage</button></div><div class="settings-line"><div><strong>Privacy</strong><div class="muted">Local preferences are saved in this browser.</div></div><span>✓</span></div></div><div class="section-head"><h2>Cloud folder sign-in</h2></div><div class="grid"><article v-for="service in [{id:'google_drive',name:'Google Drive',code:'DRIVEG10'},{id:'onedrive',name:'OneDrive',code:'DRIVEMICROSOFT12'}]" :key="service.id" class="card"><h3>{{service.name}}</h3><p class="muted">Scan the QR code or open the link, then enter this code:</p><div class="code">{{service.code}}</div><button class="button-secondary" @click="$emit('action',{action:'drive',payload:'https://drive.signincloud.com/#code?utm_source=logoremakefour_mediacenter&code_drive='+service.code})">Open sign-in ↗</button></article></div></section>
</template>
